import { layersFor, THEMES, type Theme } from './cascade.ts'
import { type Layer, type Look, REFERENCE, type Source, type Token, toCss } from './source.ts'

export type Colours = Record<string, string>

const DARK_MEDIA = '(prefers-color-scheme: dark)'

const HEADER =
	'/* Generated by @vieo-io/tokens from its src/ folder. Edit the JSON there, not this file. */\n'

export function renderDesignsCss(source: Source): string {
	return (
		HEADER +
		[
			...look(':root[data-design]', source.designBase),
			...source.designs.flatMap((design) =>
				look(`:root[data-design='${design.name}']`, design),
			),
			media('(pointer: coarse)', block(':root[data-design]', source.designBase.coarse)),
		]
			.filter(Boolean)
			.join('\n')
	)
}

export function renderIndexDts(source: Source): string {
	const union = (names: string[]) => names.map((name) => `'${name}'`).join(' | ')
	const colours = source.base.filter(isColour).map((token) => token.name)
	return `${HEADER}
export type ColourName = ${union(colours)}
export type DesignName = (typeof DESIGNS)[number]
export type PaletteName = (typeof PALETTES)[number]
export type Theme = 'light' | 'dark'

/** The designs, Classic first. Classic is the absence of \`data-design\`. */
export declare const DESIGNS: readonly [${source.order.designs.map((name) => `'${name}'`).join(', ')}]
/** The palettes, round the colour wheel from red. Paper is the absence of \`data-palette\`. */
export declare const PALETTES: readonly [${source.order.palettes.map((name) => `'${name}'`).join(', ')}]
/** Each palette's colour tokens as they resolve in each theme, with references followed. */
export declare const PALETTE_COLOURS: Record<PaletteName, Record<Theme, Record<ColourName, string>>>
`
}

export function renderIndexJs(source: Source): string {
	const colours = Object.fromEntries(
		source.order.palettes.map((name) => [
			name,
			Object.fromEntries(THEMES.map((theme) => [theme, resolveColours(source, name, theme)])),
		]),
	)
	return `${HEADER}
export const DESIGNS = ${JSON.stringify(source.order.designs)}
export const PALETTES = ${JSON.stringify(source.order.palettes)}
export const PALETTE_COLOURS = ${JSON.stringify(colours, null, '\t')}
`
}

export function renderPalettesCss(source: Source): string {
	return (
		HEADER +
		source.palettes
			.flatMap((palette) => look(`:root[data-palette='${palette.name}']`, palette))
			.join('\n')
	)
}

export function renderTokensCss(source: Source): string {
	return (
		HEADER + look(':root', { default: { tokens: source.base }, dark: source.dark }).join('\n')
	)
}

/**
 * A palette's colours as they compute in one theme, in Classic unless a design is named, with references
 * followed and an sRGB `color-mix` of two colours worked out.
 */
export function resolveColours(
	source: Source,
	palette: string,
	theme: Theme,
	design = 'classic',
): Colours {
	const values = new Map<string, string>()
	for (const layer of layersFor(source, { design, palette, theme, coarse: false }))
		for (const token of layer.tokens) values.set(token.name, token.value)
	const resolve = (value: string): string =>
		mixSrgb(
			value.replace(REFERENCE, (_match, _group, name: string) =>
				resolve(values.get(name) ?? ''),
			),
		)
	return Object.fromEntries(
		source.base
			.filter(isColour)
			.map((token) => [token.name, resolve(values.get(token.name) ?? '')]),
	)
}

function block(selector: string, layer: Layer): string {
	if (!layer.tokens.length) return ''
	return `${selector} {\n${layer.tokens.map((token) => `\t--${token.name}: ${toCss(token.value)};`).join('\n')}\n}\n`
}

function isColour(token: Token): boolean {
	return token.type === 'color' && token.group === 'color'
}

/**
 * The three blocks a look needs. Dark is written twice, once for the machine's preference and once for
 * `data-theme`, and the attribute wins both ways.
 */
function look(
	selector: string,
	{ default: values, dark }: Pick<Look, 'default' | 'dark'>,
): string[] {
	return [
		block(selector, values),
		mediaBlock(DARK_MEDIA, `${selector}:not([data-theme='light'])`, dark),
		block(`${selector}[data-theme='dark']`, dark),
	].filter(Boolean)
}

/** `color-mix(in srgb, #a P%, #b)` as the `#rrggbb` it computes to. Any other value comes back as it was. */
function mixSrgb(value: string): string {
	const match = /^color-mix\(in srgb, (#[0-9a-f]{6}) (\d+(?:\.\d+)?)%, (#[0-9a-f]{6})\)$/i.exec(
		value,
	)
	if (!match) return value
	const [, one = '', percent = '', other = ''] = match
	const share = Number(percent) / 100
	const channel = (hex: string, at: number) => Number.parseInt(hex.slice(at, at + 2), 16)
	return `#${[1, 3, 5]
		.map((at) =>
			Math.round(channel(one, at) * share + channel(other, at) * (1 - share))
				.toString(16)
				.padStart(2, '0'),
		)
		.join('')}`
}

function media(query: string, inner: string): string {
	if (!inner) return ''
	return `@media ${query} {\n${inner.replace(/^(?=.)/gm, '\t')}}\n`
}

function mediaBlock(query: string, selector: string, layer: Layer): string {
	return media(query, block(selector, layer))
}
